// Observation fields, kept separate from forecast products and their terminology.
globalThis.ObservationVariables=(()=>{
 const out={},thermal=['#5756ad','#4e91c4','#62bba8','#e6d17c','#e48357','#b74056'],blue=['#d4e8ed','#91c9d6','#4199b5','#276895','#363c83'];
 const numeric=(key,label,unit,min,max,group,note='',summary=false)=>out[key]={label,unit,min,max,dec:1,colours:unit==='°C'?thermal:blue,group,note,summary};
 const text=(key,label,group,note='')=>out[key]={label,unit:'',text:true,group,note};
 const code=(key,label,group,table)=>{numeric(key,label,'code',0,9,group,'WMO table '+table+'. Exact code and source report appear in station details.');out[key].dec=0;};
 numeric('temperature_max','Maximum temperature · SYNOP','°C',-10,35,'Temperature','Reported extreme, not a forecast or a maximum calculated from hourly readings. The duration follows the national schedule and is not encoded in this group.',true);
 numeric('temperature_min','Minimum temperature · SYNOP','°C',-15,25,'Temperature','Reported extreme, commonly in 06:00 / 18:00 summaries. Duration follows the national schedule and is not encoded in this group.',true);
 numeric('grass_min','Grass minimum temperature','°C',-15,25,'Temperature','Reported grass minimum in whole degrees; observation period follows national schedule.',true);
 numeric('wet_bulb','Wet-bulb temperature · marine','°C',-10,30,'Temperature','Reported wet-bulb temperature; kept separate from dew point.');
 numeric('gust_period','Maximum gust · reporting period','mph',0,70,'Wind','SYNOP 911ff gust over the period specified by 907tt, or the synoptic interval. Details show the reported period.');
 text('wind_variation','Wind direction variation · METAR','Wind');text('wind_shear','Runway wind shear · METAR','Wind');
 numeric('pressure_change_3h','Pressure change · 3 hours','hPa',-10,10,'Pressure');numeric('pressure_change_24h','Pressure change · 24 hours','hPa',-20,20,'Pressure');code('pressure_tendency','Pressure tendency · 3 hours','Pressure','0200');
 text('geopotential','Pressure-level geopotential · coded','Pressure','The pressure level and its original height code are retained; these groups are not sea-level pressure.');
 text('weather_codes','Exact present-weather codes · METAR','Weather & sky');text('recent_weather','Recent weather · METAR','Weather & sky');code('past_weather_1','Past weather · category 1','Weather & sky','4561 / 4531');code('past_weather_2','Past weather · category 2','Weather & sky','4561 / 4531');
 numeric('low_mid_cloud','Low / middle cloud amount','oktas',0,8,'Cloud');code('low_cloud_type','Low cloud type · SYNOP','Cloud','0513');code('mid_cloud_type','Middle cloud type · SYNOP','Cloud','0515');code('high_cloud_type','High cloud type · SYNOP','Cloud','0509');
 text('cloud_base_range','Lowest cloud-base range · SYNOP','Cloud','Height ranges from WMO table 1600; code 9 can mean ≥2,500 m or no cloud.');numeric('cloud_layer_base','Lowest layer base · SYNOP','m',0,6000,'Cloud','Reported layer base; ranges and inequality qualifiers are retained.');text('cloud_layers','All cloud layers · SYNOP','Cloud','Original layer groups retain amount, cloud genus and height code.');
 numeric('metar_cloud_base','Lowest cloud base · METAR','ft',0,15000,'Cloud');numeric('ceiling','Ceiling · METAR','ft',0,10000,'Cloud','Lowest broken/overcast cloud base, or vertical visibility in obscuration.');numeric('vertical_visibility','Vertical visibility · METAR','ft',0,5000,'Cloud');text('metar_layers','All cloud layers · METAR','Cloud');text('runway_visibility','Runway visual range · METAR','Visibility');
 code('ground_state','Ground state · SYNOP','Ground & snow','0901');code('snow_state','Snow / ice cover state','Ground & snow','0975');numeric('snow_depth','Snow depth','cm',0,100,'Ground & snow','Reported snow depth; discontinuous cover and special codes retain their meanings.');
 numeric('sunshine_1h','Sunshine duration · 1 hour','h',0,1,'Sunshine & radiation');numeric('sunshine_24h','Sunshine duration · 24 hours','h',0,16,'Sunshine & radiation','Accumulation ending at its report time.',true);
 for(const [key,label]of [['net','Net'],['global','Global solar'],['diffuse','Diffuse solar'],['downward_longwave','Downward long-wave'],['upward_longwave','Upward long-wave'],['shortwave','Short-wave']])for(const hours of [1,24])numeric(`radiation_${key}_${hours}h`,`${label} radiation · ${hours}h`,'kJ/m²',key==='net'?-1500:0,hours===1?4000:30000,'Sunshine & radiation','Accumulated radiation energy over the stated period; not forecast irradiance.',hours===24);
 numeric('wave_height','Instrumental wave height','m',0,12,'Marine');numeric('wave_period','Instrumental wave period','s',0,25,'Marine');numeric('wind_wave_height','Visual wind-wave height','m',0,12,'Marine');numeric('wind_wave_period','Visual wind-wave period','s',0,25,'Marine');
 for(const n of [1,2]){numeric(`swell_${n}_height`,`Swell ${n} height`,'m',0,12,'Marine');numeric(`swell_${n}_period`,`Swell ${n} period`,'s',0,25,'Marine');numeric(`swell_${n}_direction`,`Swell ${n} direction`,'°',0,360,'Marine','Direction swell comes from.');}
 numeric('ice_accretion','Ship ice accretion','cm',0,20,'Marine');text('ocean_profile','Subsurface ocean profile · coded','Marine','Original BUOY temperature / salinity / current profile groups with depths and quality flags; see raw report.');text('supplementary','Supplementary / national coded groups','Additional observations','Additional groups remain available as transmitted when a regional definition is needed. Station details show their codes and complete report.');
 return out;
})();
